__NUXT_JSONP__("/it/teachers", {data:[{details:{slug:"it",pageTitle:"Corsi offerti da MLI e Insegnanti | Mentor Language Institute",pageDescription:"Nei corsi di Inglese Generale, gli studenti acquisiscono le abilità linguistiche pratiche grazie all'utilizzo di materiale di uso quotidiano nel mondo reale come post di Twitter, TED talk e filmati.",title:"Corsi offerti da MLI e Insegnanti",image:"\u002Fimages\u002Fwhat-is-mli\u002Fteachers\u002Fmli-student-teachers.jpg",lists:[{title:"I corsi si concentrano sulle abilità linguistiche pratiche",description:["Nei corsi di Inglese Generale, gli studenti acquisiscono le abilità linguistiche pratiche grazie all'utilizzo di materiale di uso quotidiano nel mondo reale come post di Twitter, TED talk e filmati.  Attraverso l'utilizzo di questo materiale, gli studenti acquisiscono sistematicamente modelli di grammatica, scrittura, lettura, lessico, comprensione orale e conversazione.","Inoltre, il programma TOEFL e gli altri corsi di preparazione ai test forniscono le strategie necessarie per la risoluzione dei quesiti con i metodi più appropriati."]},{title:"Insegnanti",description:["1,200 studenti ottengono il Diploma MLI ogni anno, indice della qualità dei nostri insegnanti. Ci impegniamo costantemente al fine di migliorare le abilità dei nostri insegnanti attraverso l'osservazione, la valutazione e la partecipazione a seminari di sviluppo professionale."],checklist:[{title:"Requisiti di assunzione (elenco dei requisiti ai fini dell'assunzione degli insegnanti)",lists:["Laurea","3 anni di esperienza nell'insegnamento dell'Inglese","Certificazione in Didattica come TESOL","Competenza in ambito di Test come ad esempio TOEFL® \u002F GMAT®","Spiccate capacità comunicative","Passione e impegno nell'insegnamento"]},{title:"Metodo di Selezione",lists:["Curriculum e Diploma","Test di Grammatica Inglese","Colloquio","Lezione prova"],note:"il tasso di assunzione è inferiore al 20%."}]},{title:"Training e sistema di valutazione",description:["Al fine di mantenere elevata la qualità dell'insegnamento, MLI valuta con cadenza trimestrale."],listType:"decimal",lists:["Il giudizio espresso dagli studenti circa la qualità dei libri di testo e degli insegnanti. Gli insegnanti con un tasso di soddisfazione pari o inferiore all'85% vengono sottoposti a training di sviluppo professionale.","Osservazione della lezione e feedback da parte del team di esperti in didattica","Sviluppo professionale e seminari per il miglioramento dell'insegnamento"],note:"L'amministrazione e gli insegnanti sono impegnati quotidianamente nel migliorare la qualità dell'istruzione fornita da MLI."}],teachers:[{image:"\u002Fimages\u002Fwhat-is-mli\u002Fteachers\u002Fteacher-julie.jpg",name:"Julie"},{image:"\u002Fimages\u002Fwhat-is-mli\u002Fteachers\u002Fteacher-brian.jpg",name:"Brian"},{image:"\u002Fimages\u002Fwhat-is-mli\u002Fteachers\u002Fteacher-kelsey.jpg",name:"Kelsey"},{image:"\u002Fimages\u002Fwhat-is-mli\u002Fteachers\u002Fteacher-shawna.jpg",name:"Shawna"},{image:"\u002Fimages\u002Fwhat-is-mli\u002Fteachers\u002Fteacher-benjamin.jpg",name:"Benjamin"},{image:"\u002Fimages\u002Fwhat-is-mli\u002Fteachers\u002Fteacher-kyle.jpg",name:"Kyle"},{image:"\u002Fimages\u002Fwhat-is-mli\u002Fteachers\u002Fteacher-lindsay.jpg",name:"Lindsay"},{image:"\u002Fimages\u002Fwhat-is-mli\u002Fteachers\u002Fteacher-leo.jpg",name:"Leo"},{image:"\u002Fimages\u002Fwhat-is-mli\u002Fteachers\u002Fteacher-alex.jpg",name:"Alex"},{image:"\u002Fimages\u002Fwhat-is-mli\u002Fteachers\u002Fteacher-carl.jpg",name:"Carl"},{image:"\u002Fimages\u002Fwhat-is-mli\u002Fteachers\u002Fteacher-shenna.jpg",name:"Shenna"},{image:"\u002Fimages\u002Fwhat-is-mli\u002Fteachers\u002Fteacher-bonnie.jpg",name:"Bonnie"},{image:"\u002Fimages\u002Fwhat-is-mli\u002Fteachers\u002Fteacher-patrick.jpg",name:"Patrick"},{image:"\u002Fimages\u002Fwhat-is-mli\u002Fteachers\u002Fteacher-hubert.jpg",name:"Hubert"},{image:"\u002Fimages\u002Fwhat-is-mli\u002Fteachers\u002Fteacher-matt.jpg",name:"Matt"},{image:"\u002Fimages\u002Fwhat-is-mli\u002Fteachers\u002Fteacher-Maribel.jpg",name:"Maribel"},{image:"\u002Fimages\u002Fwhat-is-mli\u002Fteachers\u002Fteacher-Joan.jpg",name:"Joan"},{image:"\u002Fimages\u002Fwhat-is-mli\u002Fteachers\u002Fteacher-Sara.jpg",name:"Sara"},{image:"\u002Fimages\u002Fwhat-is-mli\u002Fteachers\u002Fteacher-Tom.jpg",name:"Tom"},{image:"\u002Fimages\u002Fwhat-is-mli\u002Fteachers\u002Fteacher-Gannon.jpg",name:"Gannon"}],dir:"\u002Fteachers",path:"\u002Fteachers\u002Fit",extension:".json",createdAt:"2026-10-22T16:31:31.172Z",updatedAt:"2025-05-26T12:06:27.929Z"}}],fetch:{},mutations:void 0});